<?php
declare(strict_types=1); namespace App\Services\Students;
use App\Models\{Student,User}; use Illuminate\Support\Facades\Storage; use RuntimeException; use ZipArchive;
class StudentPhotoArchiveService { public function create(string $classroom,User $actor):string { $students=Student::where('classroom_label',$classroom)->whereNotNull('photo_path')->whereNotNull('nisn')->orderBy('nisn')->get();$path=tempnam(sys_get_temp_dir(),'student-photos-');$zip=new ZipArchive;if($path===false||$zip->open($path,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Arsip foto siswa tidak dapat dibuat.');$count=0;foreach($students as $student){if(!Storage::disk('local')->exists($student->photo_path))continue;$extension=strtolower(pathinfo($student->photo_path,PATHINFO_EXTENSION));$nisn=str_replace(['/','\\'],'-',trim($student->nisn));$zip->addFile(Storage::disk('local')->path($student->photo_path),"{$nisn}.{$extension}");$count++;}$zip->close();if($count===0){@unlink($path);throw new RuntimeException('Belum ada foto siswa dengan NISN pada kelas yang dipilih.');}activity('students')->causedBy($actor)->withProperties(['classroom'=>$classroom,'photo_count'=>$count])->log('Mengunduh arsip foto siswa per kelas.');return $path;} }
